+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.btn-apply,
+.btn-clear {
+    padding: 0.5rem 1rem;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-apply {
+    background: #0078d4;
+    color: white;
+}
+
+.btn-clear {
+    background: #e0e0e0;
+    color: #333;
+}
+
+/* Main content */
+.catalog-main {
+    width: 75%;
+    flex: 1;
+}
+
+/* Toolbar */
+.catalog-toolbar {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.toolbar-sort {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+}
+
+.toolbar-sort select {
+    padding: 0.3rem 0.5rem;
+}
+
+/* Product Grid */
+.product-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
+    gap: 1.25rem;
+    margin-bottom: 1.5rem;
+}
+
+.product-card {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    overflow: hidden;
+    cursor: pointer;
+    transition: box-shadow 0.2s;
+}
+
+.product-card:hover {
+    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
+}
+
+.product-image {
+    height: 160px;
+    background: #f0f0f0;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    color: #888;
+    font-size: 0.9rem;
+}
+
+.product-info {
+    padding: 0.75rem;
+}
+
+.product-name {
+    margin: 0 0 0.4rem;
+    font-size: 1rem;
+}
+
+.product-price {
+    margin: 0 0 0.3rem;
+    font-weight: 600;
+    color: #0078d4;
+}
+
+.product-rating {
+    color: #f5a623;
+    margin-bottom: 0.4rem;
+}
+
+.badge-out-of-stock {
+    display: inline-block;
+    background: #d32f2f;
+    color: white;
+    font-size: 0.75rem;
+    padding: 0.15rem 0.5rem;
+    border-radius: 3px;
+    margin-bottom: 0.4rem;
+}
+
+.btn-add-to-cart {
+    width: 100%;
+    padding: 0.5rem;
+    border: none;
+    border-radius: 4px;
+    background: #0078d4;
+    color: white;
+    cursor: pointer;
+}
+
+.btn-add-to-cart:disabled {
+    background: #ccc;
+    cursor: not-allowed;
+}
+
+/* Pagination */
+.catalog-pagination {
+    display: flex;
+    justify-content: center;
+    gap: 0.4rem;
+    padding: 1rem 0;
+}
+
+.btn-page {
+    padding: 0.4rem 0.75rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 4px;
+    background: white;
+    cursor: pointer;
+}
+
+.btn-page.active {
+    background: #0078d4;
+    color: white;
+    border-color: #0078d4;
+}
+
+.btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* States */
+.catalog-loading,
+.catalog-empty,
+.catalog-error {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    justify-content: center;
+    padding: 3rem;
+    color: #666;
+}
+
+.catalog-error {
+    color: #d32f2f;
+}
+
+.catalog-error button {
+    margin-top: 1rem;
+    padding: 0.5rem 1rem;
+    background: #0078d4;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+

